mapper.select:
SELECT DISTINCT T.AMT from( SELECT SUM(NVL(CASE WHEN WFL_TRD_PRODUCT_DEAL.PS = 'T01' THEN (CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN ('F04','F02') THEN WFL_TRD_PRODUCT_DEAL.SHARE_AMT WHEN FIN_PRODUCT_TYPE.TYPE_8 IN ('F07','F10','F08') THEN WFL_TRD_PRODUCT_DEAL.PRIN_AMT ELSE NULL END) ELSE -1 * (CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN ('F04','F02') THEN WFL_TRD_PRODUCT_DEAL.SHARE_AMT WHEN FIN_PRODUCT_TYPE.TYPE_8 IN ('F07','F10','F08') THEN WFL_TRD_PRODUCT_DEAL.PRIN_AMT ELSE NULL END) END, 0)) AMT, WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM FROM WFL_TRD_PRODUCT_DEAL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD ON WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE ON WFL_TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
WFL_TRD_PRODUCT_DEAL.TRADE_DATE <= TO_DATE(#{searchDate},'yyyy-MM-dd') AND FIN_PRODUCT_TYPE.TYPE_8 in ('F04','F02','F08','F07','F10') AND WFL_TRD_PRODUCT_DEAL.IS_OUT_TRADE = 'N' AND WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID IS NULL AND WFL_TRD_PRODUCT_DEAL.PS IN ('T01', 'T02')
AND WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID = #{portfolioId}
AND WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID = #{secAcctId}
AND WFL_TRD_PRODUCT_DEAL.FINPROD_ID = #{finprodId}
AND nvl(WFL_TRD_PRODUCT_DEAL.INV_AIM,'999999') = #{invAim}
AND WFL_TRD_PRODUCT_DEAL.CCY = #{ccy}
AND WFL_TRD_PRODUCT_DEAL.CHL_ID = #{chlId}
GROUP BY WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM )T
